import test from 'node:test';import assert from 'node:assert/strict';
import {newAfternoonScenario,save,restore} from './simulation.js';import {currentSchedule} from './days.js';import {personalFollowups,followupGameOutcome} from './personal-followups.js';import {personalEventsAt,personalEventDefs,personalEventDefinition,beginPersonalEvent,progressPersonalEvent,pausePersonalEvent,personalEventRecord,personalEventView} from './personal-events.js';import {mapEventsAt} from './map-events.js';import {displayName} from './identity.js';
const firsts={taei:['honest','record'],yeogyeong:['compare','share'],seoyeon:['ask','boundary'],soyul:['permission','wait'],iseo:['introduce','pace']};
function position(s,id,day){s.day=day;s.clock.minute=id==='iseo'?960:780;s.location=id==='taei'?'cafe':id==='iseo'?'gym':currentSchedule(s)[id];return s;}
function start(id){return position(newAfternoonScenario('close'),id,1);}
function finish(s,id,a,b){s=beginPersonalEvent(s,id);const opts=personalEventView(s).options;s=progressPersonalEvent(s,a??opts[0][0]);s=progressPersonalEvent(restore(save(s)),b??personalEventView(s).options[0][0]);return s;}
function parent(id){return finish(start(id),id,...firsts[id]);}
test('fifteen distinct stories preserve each completed chapter and require a later meeting',()=>{assert.equal(Object.keys(personalEventDefs).length+Object.keys(personalFollowups).length,15);for(const id of Object.keys(firsts)){let s=parent(id);assert.ok(!personalEventsAt(s).some(e=>e.eventId===id+':2'));assert.throws(()=>beginPersonalEvent(s,id+':3'));s=position(s,id,2);assert.ok(personalEventsAt(s).some(e=>e.eventId===id+':2'));const savedFirst=save(s.personalEvents.records[id]);const startMinute=s.clock.minute;s=finish(s,id+':2');assert.equal(s.clock.minute,startMinute+30);assert.equal(save(s.personalEvents.records[id]),savedFirst);assert.ok(!personalEventsAt(s).some(e=>e.eventId===id+':3'));s=position(s,id,3);s=finish(s,id+':3');assert.equal(Object.values(s.personalEvents.records).filter(r=>r.status==='completed').length,3);assert.ok(!personalEventsAt(s).some(e=>e.person===id));assert.ok(s.memory.some(m=>m.includes(personalEventDefinition(id+':3').title)));}});
test('old first-event saves without new episode fields unlock safely and cannot replay completed parents',()=>{let s=parent('yeogyeong');delete s.personalEvents.records.yeogyeong.eventId;delete s.personalEvents.records.yeogyeong.episode;s=position(restore(save(s)),'yeogyeong',2);assert.ok(personalEventsAt(s).some(e=>e.eventId==='yeogyeong:2'));assert.throws(()=>beginPersonalEvent(s,'yeogyeong'));});
test('prior intrusive choices change the followup opening and records stay independent',()=>{let s=finish(start('yeogyeong'),'yeogyeong','pay','share');s=position(s,'yeogyeong',2);s=beginPersonalEvent(s,'yeogyeong:2');assert.match(personalEventView(s).opening,/돈으로 맞추자는 말/);const warm=beginPersonalEvent(position(parent('yeogyeong'),'yeogyeong',2),'yeogyeong:2');assert.notEqual(personalEventView(s).opening,personalEventView(warm).opening);});
test('saved game hands do not reroll through pause/load, and RPS outcomes match all nine pairs',()=>{let s=beginPersonalEvent(position(parent('seoyeon'),'seoyeon',2),'seoyeon:2');const roll=personalEventRecord(s).context.roll;s=pausePersonalEvent(s);s=beginPersonalEvent(restore(save(s)),'seoyeon:2');assert.equal(personalEventRecord(s).context.roll,roll);const fork=restore(save(s));s=progressPersonalEvent(s,'rock');assert.deepEqual(personalEventRecord(s).game,personalEventRecord(progressPersonalEvent(fork,'rock')).game);for(let r=0;r<3;r++)for(let i=0;i<3;i++){const result=followupGameOutcome(personalFollowups['seoyeon:2'],['rock','paper','scissors'][i],r);assert.equal(result.result,i===r?'tie':(i-r+3)%3===1?'win':'lose');}});
test('Iseo who skipped names can introduce herself in a later chapter without leaking names on the map',()=>{let s=finish(start('iseo'),'iseo','listen','pace');s=position(s,'iseo',2);const event=personalEventsAt(s).find(e=>e.person==='iseo');assert.equal(event.title,'다시 마주친 운동복 학생');assert.ok(!event.title.includes('정이서'));s=beginPersonalEvent(s,event.eventId);assert.equal(s.contacts.iseo.lastSeen.day,2);s=progressPersonalEvent(s,'steady');assert.ok(personalEventView(s).options.some(o=>o[0]==='names'));s=progressPersonalEvent(s,'names');assert.equal(displayName(s,'iseo'),'정이서');assert.equal(s.contacts.iseo.details.major,'태권도과');});
test('new map marker IDs select the actual chapter and stale location fails without mutation',()=>{let s=position(parent('soyul'),'soyul',2);assert.ok(mapEventsAt(s,s.location).some(e=>e.id==='soyul:2'));s=beginPersonalEvent(s,'soyul:2');s.location='market';const before=save(s);assert.throws(()=>progressPersonalEvent(s,'pose'));assert.equal(save(s),before);});
